-- Тема 15: варианты ответов выровнены по длине и форме (42 исправлений в 17 вопросах), ключи не меняются.
-- Источник: scripts/questions/073_option_length_topic15.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'В чём суть физической репликации?', 'Мастер передаёт журнальные записи, реплика их проигрывает', 'Реплика проигрывает записи журнала мастера', 'Реплика всё время восстанавливается по журналу мастера.', 'Мастер передаёт журнальные записи, а реплика всё время восстанавливается по ним.'),
        ('option', 'В чём суть физической репликации?', 'Передаются SQL-команды', 'Мастер передаёт реплике тексты SQL-команд', 'Команды SQL не передаются.', NULL),
        ('option', 'В чём суть физической репликации?', 'Копируются изменённые строки таблиц', 'Мастер передаёт изменённые строки таблиц', 'Изменения строк передаёт логическая репликация.', NULL),
        ('option', 'Какая совместимость серверов нужна для физической репликации?', 'Только на уровне протокола', 'Совместимость протокола, двоичная не нужна', 'Так для логической репликации (при binary = true нужны ещё совместимые двоичные форматы типов).', NULL),
        ('option', 'Какая совместимость серверов нужна для физической репликации?', 'Двоичная: та же платформа и основная версия PostgreSQL', 'Двоичная: та же платформа и основная версия', 'Записи применяются механически, без понимания смысла.', NULL),
        ('option', 'Какая совместимость серверов нужна для физической репликации?', 'Одинаковые имена баз данных', 'Одинаковые имена баз данных и ролей', 'Имена баз здесь ни при чём, реплицируется весь кластер.', NULL),
        ('option', 'Что можно реплицировать физической репликацией?', 'Отдельную базу данных', 'Отдельную базу данных кластера', 'Журнал общий для кластера, отдельную базу не выделить.', NULL),
        ('option', 'Что можно реплицировать физической репликацией?', 'Отдельную таблицу', 'Отдельную таблицу или их набор', 'Отдельную таблицу реплицирует логическая репликация.', NULL),
        ('option', 'Что можно реплицировать физической репликацией?', 'Отдельную схему', 'Отдельную схему вместе с данными', 'Журнал общий для кластера, отдельную схему не выделить.', NULL),
        ('option', 'Что будет при hot_standby = off на реплике?', 'Реплика начинает принимать запись', 'Реплика начинает принимать запись от клиентов', 'Запись на реплике невозможна в любом режиме.', NULL),
        ('option', 'Что будет при hot_standby = off на реплике?', 'Репликация останавливается', 'Применение журнала на реплике останавливается', 'Репликация продолжается.', NULL),
        ('option', 'Что будет при hot_standby = off на реплике?', 'Реплика работает в режиме тёплого резерва, подключения к ней невозможны', 'Реплика работает без подключений клиентов', 'Реплика применяет журнал, но клиенты к ней не подключаются.', 'Реплика работает в режиме тёплого резерва: применяет журнал, но клиенты к ней не подключаются.'),
        ('option', 'Что будет при hot_standby = off на реплике?', 'Включается синхронный режим', 'Включается синхронный режим репликации', 'Синхронность настраивается на основном сервере.', NULL),
        ('option', 'Как работает фиксация при synchronous_commit = on и синхронной реплике?', 'Фиксация ждёт подтверждения, что реплика надёжно записала журнальные записи на диск', 'Фиксация ждёт, пока реплика сохранит журнал на диск', 'Данные не пропадут даже при выходе мастера из строя.', 'Фиксация ждёт подтверждения, что реплика надёжно записала журнальные записи на диск, поэтому данные не пропадут даже при выходе мастера из строя.'),
        ('option', 'Как работает фиксация при synchronous_commit = on и синхронной реплике?', 'Журнал на мастере отключается', 'Журнал на мастере отключается до подтверждения', 'Журнал не отключается.', NULL),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Реплика подтверждает каждую фиксацию', 'Реплика подтверждает мастеру каждую фиксацию', 'Подтверждение фиксации — это синхронная репликация.', NULL),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Ускоряется передача WAL', 'Ускоряется передача WAL с мастера на реплику', 'Скорость передачи журнала не меняется.', NULL),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Включается каскадная репликация', 'Включается каскадная репликация через реплику', 'Каскад настраивается иначе.', NULL),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Мастер учитывает горизонт запросов реплики, и очистка не удаляет нужные им версии', 'Мастер не удаляет версии, нужные запросам реплики', 'Пока работает соединение, реплика сообщает мастеру горизонт своих запросов, и очистка на мастере не удаляет версии, нужные этим запросам.', NULL),
        ('option', 'Как выполняется переход на реплику при сбое мастера?', 'Реплика сама становится мастером через 30 секунд', 'Реплика сама становится мастером через 30 секунд простоя', 'Такого механизма нет.', NULL),
        ('option', 'Что верно для каскадной репликации?', 'При включённом hot_standby_feedback сведения о нужном репликам горизонте очистки передаются по каскаду до основного сервера', 'Обратная связь hot_standby_feedback доходит до мастера', 'Да. Так основной сервер не удаляет версии строк, нужные запросам на репликах. Это не каскадная синхронная фиксация.', NULL),
        ('option', 'Что верно для каскадной репликации?', 'Дальние реплики отстают не больше ближних', 'Дальние реплики отстают не больше, чем ближние', 'Чем дальше реплика от мастера, тем больше может быть отставание.', NULL),
        ('option', 'Почему при wal_level = minimal физическая репликация невозможна?', 'Часть изменений сразу записывается на диск и не попадает в журнал', 'Часть изменений не попадает в журнал', 'Реплике нужны все данные из журнала, а на этом уровне их недостаточно.', 'Часть изменений сразу записывается на диск и не попадает в журнал, а реплике нужны все данные из журнала.'),
        ('option', 'Как настраивают реплику для долгих аналитических запросов?', 'Реплика откладывает применение журнальных записей, которые конфликтуют с запросами', 'Реплика откладывает записи, конфликтующие с запросами', 'Данные на ней могут отставать, для отчётов это обычно не страшно.', 'Реплика откладывает применение журнальных записей, которые конфликтуют с запросами (max_standby_streaming_delay); данные на ней могут отставать, для отчётов это обычно не страшно.'),
        ('option', 'Как настраивают реплику для долгих аналитических запросов?', 'Включают синхронный режим фиксации', 'Включают синхронный режим фиксации на мастере', 'Он нужен для надёжности хранения, а не для отчётов.', NULL),
        ('option', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', 'Да, при синхронной репликации', 'Да, при синхронной репликации всё согласовано', 'Согласованность между серверами не гарантируется даже в этом случае.', NULL),
        ('option', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', 'Нет, даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере', 'Нет, даже при синхронной репликации данные могут расходиться', 'Согласованное чтение гарантировано только при работе с одним сервером.', 'Даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере. Согласованное чтение гарантировано только при работе с одним сервером.'),
        ('option', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', 'Да, но только для каскадной репликации', 'Да, если используется каскадная репликация', 'Для каскада это тем более не гарантируется.', NULL),
        ('option', 'От каких реплик каскада основной сервер получает обратную связь hot_standby_feedback, если она включена?', 'Только от первой реплики в цепочке', 'От первой реплики в цепочке', 'Обратная связь поступает от всех реплик.', NULL),
        ('option', 'От каких реплик каскада основной сервер получает обратную связь hot_standby_feedback, если она включена?', 'Только от последней реплики в цепочке', 'От последней реплики в цепочке', 'Обратная связь поступает от всех реплик.', NULL),
        ('option', 'Для чего нужна реплика с отложенным применением журнальных записей?', 'Чтобы посмотреть данные на момент в прошлом и восстановиться после ошибки пользователя', 'Чтобы исправить ошибку пользователя по данным прошлого', 'Реплика применяет изменения с заданной задержкой, поэтому они становятся видны позже.', 'Реплика применяет изменения с заданной задержкой: на ней можно посмотреть данные на момент в прошлом и восстановиться после ошибки пользователя.'),
        ('option', 'Для чего нужна реплика с отложенным применением журнальных записей?', 'Чтобы разгрузить основной сервер от записи', 'Чтобы разгрузить основной сервер от операций записи', 'Записи все равно выполняются только на основном сервере.', NULL),
        ('option', 'Из чего создают физическую реплику?', 'Из пустого кластера после initdb', 'Из пустого кластера, созданного initdb', 'У нового кластера другой идентификатор системы, и журнал основного сервера к нему не применить.', NULL),
        ('option', 'Из чего создают физическую реплику?', 'Из логической копии, сделанной pg_dump', 'Из логической копии основного сервера через pg_dump', 'Логическая копия не годится: реплике нужны те же файлы данных и тот же идентификатор системы, что у основного сервера.', NULL),
        ('option', 'Из чего создают физическую реплику?', 'Командой CREATE SUBSCRIPTION', 'Командой CREATE SUBSCRIPTION на будущей реплике', 'Эта команда относится к логической репликации.', NULL),
        ('option', 'Что делает реплика с настроенным чтением из архива (restore_command), если очередную журнальную запись не удаётся получить по протоколу репликации?', 'Пытается прочитать соответствующий файл из архива сегментов WAL', 'Читает нужный сегмент WAL из архива', 'Файловую репликацию используют как дополнение к потоковой.', 'Пытается прочитать соответствующий файл из архива сегментов WAL: файловую репликацию используют как дополнение к потоковой.'),
        ('option', 'Что делает реплика с настроенным чтением из архива (restore_command), если очередную журнальную запись не удаётся получить по протоколу репликации?', 'Останавливается навсегда', 'Останавливается до ручного вмешательства', 'Она продолжает попытки получить запись, в том числе из архива.', NULL),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Основной сервер автоматически переключается в асинхронный режим', 'Основной сервер переходит в асинхронный режим', 'Автоматического переключения нет.', NULL),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Транзакции откатываются с ошибкой', 'Транзакции откатываются с ошибкой таймаута', 'Фиксация ждёт подтверждения, а не откатывается.', NULL),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Транзакции фиксируются, как обычно', 'Транзакции фиксируются, как без реплики', 'Нет. Так было бы при асинхронной репликации или если бы подтвердить запись мог другой кандидат из synchronous_standby_names.', NULL),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Фиксация не завершается, пока реплика не подтвердит, что журнальные записи сохранены', 'Фиксация будет ждать подтверждения от этой реплики', 'Да. Заменить остановленную реплику некому, поэтому COMMIT ждёт её подтверждения. Именно так проверяют синхронный режим в практике курса.', 'Фиксация не завершается, пока реплика не подтвердит, что журнальные записи сохранены: заменить остановленную реплику некому. Именно так проверяют синхронный режим в практике курса.'),
        ('option', 'Для решения каких задач применяют физическую репликацию?', 'Репликация только отдельных таблиц', 'Репликация отдельных таблиц кластера', 'Физически реплицируется только весь кластер.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
